#include <iostream>
#include <string>

class Vehicle {
public:
    Vehicle(const std::string& name, int wheels) : name_(name), wheels_(wheels) {
        std::cout << "Vehicle " << name_ << " created\n";
    }
    void info() const {
        std::cout << name_ << " has " << wheels_ << " wheels\n";
    }

protected:
    std::string name_;
    int wheels_;
};

class Bike : public Vehicle {
public:
    Bike(const std::string& name, int bells) : Vehicle(name, 2), bells_(bells) {
        std::cout << "Bike " << name_ << " created\n";
    }
    void ringBell() const {
        std::cout << name_ << " (" << wheels_ << " wheels):";
        for (int i = 0; i < bells_; ++i) {
            std::cout << " ring";
        }
        std::cout << '\n';
    }

private:
    int bells_;
};

int main() {
    std::string name = "";
    int bells = 0;
    std::cin >> name >> bells;
    const Bike bike(name, bells);
    bike.info();
    bike.ringBell();
    return 0;
}

steps.body:
Mark a member function `virtual` in the base when derived classes should replace it. Each derived class then writes its own version and tags it `override`.

```cpp
class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const { return 0.0; }
};
class Square : public Shape {
public:
    double area() const override { return side_ * side_; }
private:
    double side_ = 1.0;
};
```

Now a call through a `const Shape&` or a `Shape*` picks the version of the real object at run time. This is *dynamic dispatch*. With g++, each object carries a hidden 8 byte pointer to its class's table of virtual functions, and the call goes through that table.

- Without `virtual`, the call is chosen by the declared type, so the base version runs even for a Square.
- Always write `override`. If the signature does not match, for example a missing `const`, the compiler reports an error instead of silently adding a new function.
- Copying a Square into a plain `Shape` by value *slices* it: Shape's copy constructor copies only the Shape part, and calls run the base version. Pass by reference or pointer.
- Give every class with virtual functions `virtual ~Shape() = default;`. `= default` asks for the destructor the compiler would generate, now virtual. Step 4 shows why.

example.code:
#include <iomanip>
#include <iostream>
#include <string>

const double PI = 3.14159265358979;

class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const { return 0.0; }
    virtual std::string name() const { return "shape"; }
};

class Circle : public Shape {
public:
    explicit Circle(double radius) : radius_(radius) {}
    double area() const override { return PI * radius_ * radius_; }
    std::string name() const override { return "circle"; }

private:
    double radius_;
};

class Square : public Shape {
public:
    explicit Square(double side) : side_(side) {}
    double area() const override { return side_ * side_; }
    std::string name() const override { return "square"; }

private:
    double side_;
};

void report(const Shape& s) {
    std::cout << s.name() << ' ' << s.area() << '\n';
}

int main() {
    std::cout << std::fixed << std::setprecision(2);
    const Circle circle(2.0);
    const Square square(3.0);
    report(circle);
    report(square);
    const Shape* p = &square;
    std::cout << "pointer: " << p->name() << '\n';
    const Shape copy = circle; // slices: only the Shape part is copied
    report(copy);
    return 0;
}

