#include <iomanip>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

class Account {
public:
    Account(const std::string& owner, int transactions)
        : owner_(owner), transactions_(transactions) {}
    virtual ~Account() = default;
    virtual double monthlyFee() const = 0;
    virtual std::string kind() const = 0;
    std::string owner() const { return owner_; }

protected:
    std::string owner_;
    int transactions_;
};

class Basic : public Account {
public:
    Basic(const std::string& owner, int transactions) : Account(owner, transactions) {}
    double monthlyFee() const override { return 2.0 + 0.5 * transactions_; }
    std::string kind() const override { return "basic"; }
};

class Premium : public Account {
public:
    Premium(const std::string& owner, int transactions) : Account(owner, transactions) {}
    double monthlyFee() const override { return 12.0; }
    std::string kind() const override { return "premium"; }
};

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<std::unique_ptr<Account>> accounts;
    for (int i = 0; i < n; ++i) {
        std::string type = "";
        std::string owner = "";
        int transactions = 0;
        std::cin >> type >> owner >> transactions;
        if (type == "basic") {
            accounts.push_back(std::make_unique<Basic>(owner, transactions));
        } else {
            accounts.push_back(std::make_unique<Premium>(owner, transactions));
        }
    }
    std::cout << std::fixed << std::setprecision(2);
    double total = 0.0;
    for (const auto& a : accounts) {
        std::cout << a->owner() << ' ' << a->kind() << ' ' << a->monthlyFee() << '\n';
        total += a->monthlyFee();
    }
    std::cout << "total " << total << '\n';
    return 0;
}

steps.body:
Destruction runs in the reverse order of construction: the derived destructor body runs first, then the base destructor. That only works if the right destructor is found.

```cpp
std::unique_ptr<Base> p = std::make_unique<Derived>(1);
// p is destroyed: ~Derived runs, then ~Base
```

A unique_ptr deletes through the type it holds, here `Base*`. With `virtual ~Base()`, that delete dispatches like any virtual call and runs `~Derived` first. Without `virtual`, it is undefined behavior and in practice skips `~Derived`, so whatever the derived part owns leaks. That is why every class with virtual functions gets a virtual destructor, even an empty `= default` one. A destructor that prints, as below, is written out instead and still marked `virtual`. Derived destructors are virtual automatically, and you mark them `override`. One more gotcha: inside a constructor or destructor, a virtual call runs the version of the class being built or destroyed, never a more derived one.

When a `std::vector` is destroyed, libstdc++ destroys its elements front to back, but the standard leaves that order unspecified. When the order matters, empty the vector yourself:

```cpp
while (!items.empty()) {
    items.pop_back(); // destroys the last element now
}
```

Each `pop_back` destroys the back element, so objects die last in, first out.

example.code:
#include <iostream>
#include <memory>
#include <vector>

class Base {
public:
    explicit Base(int id) : id_(id) {
        std::cout << "Base " << id_ << '\n';
    }
    virtual ~Base() {
        std::cout << "~Base " << id_ << '\n';
    }

protected:
    int id_;
};

class Derived : public Base {
public:
    explicit Derived(int id) : Base(id) {
        std::cout << "Derived " << id_ << '\n';
    }
    ~Derived() override {
        std::cout << "~Derived " << id_ << '\n';
    }
};

int main() {
    std::vector<std::unique_ptr<Base>> items;
    items.push_back(std::make_unique<Derived>(1));
    items.push_back(std::make_unique<Derived>(2));
    while (!items.empty()) {
        items.pop_back();
    }
    std::cout << "done\n";
    return 0;
}

