#include <iostream>
#include <memory>
#include <vector>

class Widget {
public:
    explicit Widget(int id) : id_(id) {
        std::cout << "Widget " << id_ << '\n';
    }
    virtual ~Widget() {
        std::cout << "~Widget " << id_ << '\n';
    }

protected:
    int id_;
};

class Button : public Widget {
public:
    explicit Button(int id) : Widget(id) {
        std::cout << "Button " << id_ << '\n';
    }
    ~Button() override {
        std::cout << "~Button " << id_ << '\n';
    }
};

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<std::unique_ptr<Widget>> widgets;
    for (int id = 1; id <= n; ++id) {
        widgets.push_back(std::make_unique<Button>(id));
    }
    while (!widgets.empty()) {
        widgets.pop_back();
    }
    std::cout << "done\n";
    return 0;
}
